-- Nunca editar manualmente.

-- Sistemas de referencia da expansao anatomica (conflitos preservam o seed V2).
INSERT INTO anatomical_system (code, name, description) VALUES
  ('SYS-ESQ', 'Esqueleto', NULL),
  ('SYS-MUS', 'Muscular', NULL),
  ('SYS-CAR', 'Coração', NULL),
  ('SYS-SEN', 'Sensoriais', NULL),
  ('SYS-ART', 'Artérias', NULL),
  ('SYS-VEN', 'Veias', NULL),
  ('SYS-NER', 'Nervoso', NULL),
  ('SYS-RES', 'Respiratório', NULL),
  ('SYS-DIG', 'Digestório', NULL),
  ('SYS-URI', 'Urinário', NULL),
  ('SYS-LIN', 'Linfático', NULL),
  ('SYS-END', 'Endócrino', NULL),
  ('SYS-REP', 'Reprodutor', NULL),
  ('SYS-INT', 'Superfície', NULL),
  ('SYS-CON', 'Conjuntivo', NULL) ON CONFLICT (code) DO NOTHING;

